moon.shadow.mapSize.set(2048, 2048); moon.shadow.camera.left = -34; moon.shadow.camera.right = 34; moon.shadow.camera.top = 34; moon.shadow.camera.bottom = -34; moon.shadow.bias = -.00035; scene.add(moon);
